c/styles.css?44b2","webpack://webpack-template/./src/selfplacementplay.js","webpack://webpack-template/./src/appController.js","webpack://webpack-template/./src/index.js"],"sourcesContent":["// Imports\nimport ___CSS_LOADER_API_SOURCEMAP_IMPORT___ from \"../node_modules/css-loader/dist/runtime/sourceMaps.js\";\nimport ___CSS_LOADER_API_IMPORT___ from \"../node_modules/css-loader/dist/runtime/api.js\";\nvar ___CSS_LOADER_EXPORT___ = ___CSS_LOADER_API_IMPORT___(___CSS_LOADER_API_SOURCEMAP_IMPORT___);\n// Module\n___CSS_LOADER_EXPORT___.push([module.id, `*,\n*::before,\n*::after {\n  box-sizing: border-box;\n  font-family: 'Times New Roman', Times, serif;\n  margin: 0;\n  padding: 0;\n}\n\nbody {\n  background-color: rgb(152, 182, 182);\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  gap: 0.25rem;\n}\n\n.staging-div {\n  display: flex;\n  flex-direction: column;\n  gap: 2px;\n}\n\n.toggle-button {\n  width: clamp(20.7rem, 42vw, 29rem);\n  height: clamp(1rem, 4vw, 2rem);\n  font-size: clamp(0.5rem, 2.5vw, 1rem);\n  font-weight: bold;\n  background-color: rgb(206, 191, 191);\n  color: white;\n  background-color: black;\n}\n\n.game-boards-container {\n  margin-top: 0.7rem;\n  display: flex;\n  gap: 0.625rem;\n  flex-wrap: wrap;\n  justify-content: center;\n}\n\n.player-board {\n  display: grid;\n  grid-template-rows: repeat(10, 1fr);\n  width: clamp(20.7rem, 42vw, 29rem);\n  height: clamp(20.7rem, 44.7vw, 29rem);\n  border: solid 2px rgb(22, 10, 10);\n}\n\n.computer-board {\n  display: grid;\n  grid-template-rows: repeat(10, 1fr);\n  width: clamp(20.7rem, 42vw, 29rem);\n  height: clamp(20.7rem, 44.7vw, 29rem);\n  border: solid 2px rgb(18, 13, 13);\n}\n\n.grid-rows {\n  display: grid;\n  grid-template-columns: repeat(10, 1fr);\n}\n\n.grid-cols {\n  display: grid;\n  grid-template-columns: repeat(10, 1fr);\n  background-color: white;\n  border: solid 0.5px rgb(0, 0, 0);\n}\n\n.ship {\n  background-color: rgb(1, 1, 1);\n}\n\n.hit-ships {\n  display: flex;\n  justify-content: center;\n  background-color: red;\n  align-items: center;\n}\n\n.missed-ships {\n  background-color: gray;\n  display: flex;\n  justify-content: center;\n  font-size: 1.24rem;\n  align-items: center;\n  font-weight: bold;\n}\n\n.ships-staging-container {\n  display: flex;\n  padding: 2px;\n  gap: 2px; /* Added spacing so ships don't bunch together */\n  width: clamp(20.7rem, 42vw, 29rem);\n  height: clamp(20.7rem, 44.7vw, 29rem);\n  border: solid 5px rgb(0, 0, 0);\n  flex-wrap: wrap;\n  align-content: start;\n\n  /* DEFAULT STATE: Row layout (Ships sit next to each other horizontally) */\n  flex-direction: row;\n}\n\n.staging-ships {\n  display: flex;\n  /* DEFAULT STATE: Vertical orientation (Cells stack downward) */\n  flex-direction: column;\n  gap: 1px; /* Small spacing between individual red boxes */\n  touch-action: none;\n  user-select: none;\n  -webkit-user-select: none;\n}\n\n.staging-ship-cell {\n  background-color: rgb(0, 0, 0);\n  width: clamp(1.87rem, 3.8vw, 2.7rem);\n  height: clamp(1.87rem, 3.8vw, 2.7rem);\n  border: 1px solid grey;\n  flex-shrink: 0; /* Prevents cells from squeezing out of shape */\n}\n\n.ships-staging-container.horizontal-layout {\n  flex-direction: column;\n}\n\n/* Changes the internal ship layout so cells run left-to-right */\n.ships-staging-container.horizontal-layout .staging-ships {\n  flex-direction: row;\n}\n\n.welcome-container {\n  display: flex;\n  flex-direction: column;\n  justify-content: center;\n  align-items: center;\n  width: 100%;\n  gap: 1rem;\n}\n\nh1 {\n  font-size: clamp(0.625rem, 3vw, 1.8rem);\n  text-align: center;\n}\n\nh2 {\n  font-size: clamp(0.75rem, 2vw, 1.2rem);\n  margin: 0;\n  padding-bottom: 2px;\n}\n\nli {\n  font-size: clamp(0.625rem, 1.5vw, 1rem);\n  font-weight: bold;\n  text-align: start;\n  padding: 0.2rem;\n}\n\n.reset-button-holder {\n  margin-top: 0.25rem;\n  display: flex;\n  justify-content: center;\n  align-items: center;\n  gap: 1.25rem;\n  width: clamp(10rem, 67