dataset.row);\n        let dropCol = Number(event.target.dataset.col);\n        const dropData = Number(event.dataTransfer.getData('shipIndex'));\n        let dropShip = ships[dropData];\n        let shipPlacement = playerOneBoard.placeShip(\n          dropShip,\n          dropRow,\n          dropCol,\n          currentDirection\n        );\n        if (shipPlacement) {\n          renderShips(playerOneBoard, playerOneContainer);\n          let placedShip = container.querySelector(\n            `[data-ship-index=\"${dropData}\"]`\n          );\n          placedShip.remove();\n          directionToggleButton.textContent =\n            'Click Here To Change Ship Direction';\n          if (stagingContainer.childElementCount === 0) {\n            stagingContainer.style.display = 'none';\n            stagingText.style.display = 'none';\n            directionToggleButton.style.display = 'none';\n            attackComputer();\n          }\n        } else {\n          alert(\"Ship Can't be placed here\");\n        }\n      });\n    } else {\n      pageBody.addEventListener(\n        'touchmove',\n        (event) => {\n          if (draggedShipIndex === null) {\n            return;\n          }\n          event.preventDefault();\n\n          const touch = event.touches[0];\n          const xCoordinate = touch.clientX;\n          const yCoordinate = touch.clientY;\n\n          draggedShipElement.style.left = `${xCoordinate - draggedShipElement.offsetWidth / 2}px`;\n          draggedShipElement.style.top = `${yCoordinate - draggedShipElement.offsetHeight / 2}px`;\n\n          draggedShipElement.style.display = 'none';\n          const combinedCoordinates = document.elementFromPoint(\n            xCoordinate,\n            yCoordinate\n          );\n          draggedShipElement.style.display = '';\n\n          if (combinedCoordinates === null) {\n            return;\n          }\n          if (lastHoveredCell !== null) {\n            lastHoveredCell.classList.remove('hovered-cell');\n          }\n          if (\n            combinedCoordinates.dataset.row &&\n            combinedCoordinates.dataset.col\n          ) {\n            lastHoveredCell = combinedCoordinates;\n            lastHoveredCell.classList.add('hovered-cell');\n          } else {\n            lastHoveredCell = null;\n          }\n        },\n        { passive: false }\n      );\n\n      function cleanUp() {\n        if (draggedShipElement !== null) {\n          draggedShipElement.style.position = '';\n          draggedShipElement.style.pointerEvents = 'auto';\n        }\n        if (lastHoveredCell !== null) {\n          lastHoveredCell.classList.remove('hovered-cell');\n        }\n        draggedShipIndex = null;\n        draggedShipElement = null;\n      }\n\n      pageBody.addEventListener('touchend', () => {\n        if (draggedShipIndex === null || lastHoveredCell === null) {\n          cleanUp();\n          return;\n        }\n        let rowForDrop = Number(lastHoveredCell.dataset.row);\n        let colForDrop = Number(lastHoveredCell.dataset.col);\n        let droppedShip = actualShip;\n        let touchPlacement = playerOneBoard.placeShip(\n          droppedShip,\n          rowForDrop,\n          colForDrop,\n          currentDirection\n        );\n        if (touchPlacement) {\n          renderShips(playerOneBoard, playerOneContainer);\n          let placedShip = container.querySelector(\n            `[data-ship-index=\"${draggedShipIndex}\"]`\n          );\n          placedShip.remove();\n          directionToggleButton.textContent =\n            'Click Here To Change Ship Direction';\n          if (stagingContainer.childElementCount === 0) {\n            stagingContainer.style.display = 'none';\n            stagingText.style.display = 'none';\n            directionToggleButton.style.display = 'none';\n            attackComputer();\n          }\n          cleanUp();\n        } else {\n          alert(\"Ship Can't be placed here\");\n          cleanUp();\n        }\n      });\n    }\n  }\n\n  stagingHolder();\n  appendPlayerBoard();\n  appendComputerBoard();\n  renderGameBoard(10, 10, playerOneContainer);\n  renderGameBoard(10, 10, playerTwoContainer);\n  renderShipStaging(playerOneShips, stagingContainer);\n  renderShips(playerOneBoard, playerOneContainer);\n  createAndPlaceComShips();\n}\n\nexport function selfPlacementGame() {\n  clearBoards();\n  createPlayerGameSession();\n  dialog.close();\n}\n","// appController.js\n\nimport {\n  selfPlacementGame,\n  selfResetButton,\n  selfSwitchButton,\n} from './selfplacementplay.js';\nimport {\n  randomBoardPlay,\n  randomResetButton,\n  randomSwitchButton,\n} from './gameplay.js';\nimport {\n  pageBody,\n  clearBoards,\n  resetButtonHolder,\n  dialog,\n} from './gameplayresources.js';\n\nconst randomPlacementButton = document.querySelector(\n  '.random-placement-button'\n);\nrandomPlacementButton.addEventListener('click', () => {\n  resetButtonHolder.append(randomResetButton, randomSwitchButton);\n  pageBody.appendChild(resetButtonHolder);\n  dialog.close();\n});\n\nexport const selfPlacementButton = document.querySelector(\n  '.self-placement-button'\n);\n\nselfPlacementButton.addEventListener('click', () => {\n  resetButtonHolder.append(selfResetButton, selfSwitchButton);\n  pageBody.appendChild(resetButtonHolder);\n  selfPlacementGame();\n});\n\nrandomResetButton.addEventListener('click', () => {\n  resetButtonHolder.style.display = 'none';\n  clearBoards();\n  randomBoardPlay();\n});\n\nrandomSwitchButton.addEventListener('click', () => {\n  resetButtonHolder.style.display = 'none';\n  clearBoards();\n  resetButtonHolder.replaceChildren();\n  resetButtonHolder.append(selfResetButton, selfSwitchButton);\n  pageBody.append(resetButtonHolder);\n  selfPlacementGame();\n});\n\nselfResetButton.addEventListener('click', () => {\n  resetButtonHolder.style.display = 'none';\n  clearBoards();\n  selfPlacementGame();\n});\n\nselfSwitchButton.addEventListener('click', () => {\n  resetButtonHolder.style.display = 'none';\n  clearBoards();\n  resetButtonHolder.replaceChildren();\n  resetButtonHolder.append(randomResetButton, randomSwitchButton);\n  pageBody.append(resetButtonHolder);\n  randomBoardPlay();\n});\n","// index.js\n\nimport { randomBoardPlay } from './gameplay.js';\nimport { dialog } from './gameplayresources.js';\nimport './styles.css';\nimport './appController.js';\n\ndialog.showModal();\nrandomBoardPlay();\n"],"names":["___CSS_LOADER_EXPORT___","push","module","id","exports","cssWithMappingToString","list","toString","this","map","item","content","needLayer","concat","length","join","i","modules","media","dedupe","supports","layer","undefined","alreadyImportedModules","k","_k","cssMapping","btoa","base64","unescape","encodeURIComponent","JSON","stringify","data","sourceMapping","stylesInDOM","getIndexByIdentifier","identifier","result","modulesToDom","options","idCountMap","identifiers","base","count","indexByIdentifier","obj","css","sourceMap","references","updater","addElementStyle","byIndex","splice","api","domAPI","update","newObj","remove","lastIdentifiers","newList","index","newLastIdentifiers","_i","_index","memo","insert","style","target","styleTarget","document","querySelector","window","HTMLIFrameElement","contentDocument","head","e","getTarget","Error","appendChild","element","createElement","setAttributes","attributes","styleElement","nonce","setAttribute","insertStyleElement","styleTagTransform","apply","parentNode","removeChild","removeStyleElement","styleSheet","cssText","firstChild","createTextNode","__webpack_module_cache__","__webpack_require__","moduleId","cachedModule","__webpack_modules__","renderGameBoard","rows","cols","board","boardRow","classList","add","j","boardCols","dataset","row","col","renderShips","gameBoard","container","playingBoard","boardCoordinate","shipCoordinate","updateCell","textContent","n","getter","__esModule","d","a","definition","key","o","Object","defineProperty","enumerable","get","prop"