r][c] !== null) {\n            return false;\n          }\n        }\n      }\n    }\n\n    for (let i = 0; i < ship.length; i++) {\n      if (direction === 'vertical') {\n        let currentRow = startRow + i;\n        this.playingBoard[currentRow][startCol] = ship;\n      } else if (direction === 'horizontal') {\n        let currentColumn = startCol + i;\n        this.playingBoard[startRow][currentColumn] = ship;\n      }\n    }\n    return true;\n  }\n\n  receiveAttack(row, col) {\n    if (row < 0 || row > this.rows - 1 || col < 0 || col > this.cols - 1) {\n      return false;\n    }\n\n    const checkedCoordinates = `${row},${col}`;\n    if (this.attackedCoordinates.includes(checkedCoordinates)) {\n      return 'already attacked';\n    } else {\n      this.attackedCoordinates.push(checkedCoordinates);\n    }\n\n    if (this.playingBoard[row][col] !== null) {\n      this.playingBoard[row][col].hit();\n      return 'hit';\n    } else {\n      this.missedAttacks.push(checkedCoordinates);\n      return 'miss';\n    }\n  }\n\n  areAllShipsSunk() {\n    // if (this.playingBoard.every((row) => row.every((cell) => cell === null))) {\n    //   return 'empty board';\n    // }\n\n    for (let i = 0; i < this.playingBoard.length; i++) {\n      for (let j = 0; j < this.playingBoard[i].length; j++) {\n        let cellContent = this.playingBoard[i][j];\n        if (cellContent !== null && !cellContent.isSunk()) {\n          return false;\n        }\n      }\n    }\n    return true;\n  }\n}\n","// Players.js\n\nimport { GameBoard } from './gameBoard.js';\n\nexport class Player {\n  constructor(name, isComputer = false) {\n    this.name = name;\n    this.gameBoard = new GameBoard();\n    this.isComputer = isComputer;\n  }\n}\n","// gamePlayResources.js\n\nimport { Ship } from './ship.js';\nimport { Player } from './players.js';\nimport { updateCell } from './renderGame.js';\n\nexport const pageBody = document.querySelector('body');\nexport const mainStagingContainer = document.querySelector('.staging-div');\nexport const dialog = document.querySelector('dialog');\nexport const gameBoardsContainer = document.createElement('div');\ngameBoardsContainer.classList.add('game-boards-container');\n\nexport const resetButtonHolder = document.createElement('div');\nresetButtonHolder.style.display = 'none';\nresetButtonHolder.classList.add('reset-button-holder');\ndialog.showModal();\n\nlet targetQueue = [];\n\nexport function placeShipRandomly(board, ship) {\n  let placementDirection;\n\n  if (Math.random() >= 0.5) {\n    placementDirection = 'vertical';\n  } else {\n    placementDirection = 'horizontal';\n  }\n\n  let attackedCol = Math.floor(Math.random() * 10);\n  let attackedRow = Math.floor(Math.random() * 10);\n  let shipPlacement = board.placeShip(\n    ship,\n    attackedRow,\n    attackedCol,\n    placementDirection\n  );\n  while (!shipPlacement) {\n    if (Math.random() >= 0.5) {\n      placementDirection = 'vertical';\n    } else {\n      placementDirection = 'horizontal';\n    }\n    attackedCol = Math.floor(Math.random() * 10);\n    attackedRow = Math.floor(Math.random() * 10);\n    shipPlacement = board.placeShip(\n      ship,\n      attackedRow,\n      attackedCol,\n      placementDirection\n    );\n  }\n}\n\nfunction getAdjacentCoordinates(row, col) {\n  let upperRow = { row: row - 1, col: col };\n  let lowerRow = { row: row + 1, col: col };\n  let leftCol = { row: row, col: col - 1 };\n  let rightCol = { row: row, col: col + 1 };\n  return [upperRow, lowerRow, leftCol, rightCol];\n}\n\nexport function createGameSession() {\n  const playerOne = new Player('Jas');\n  const playerTwo = new Player('Claude', true);\n  let currentPlayer = playerOne;\n\n  const playerOneContainer = document.createElement('div');\n  const playerTwoContainer = document.createElement('div');\n\n  const playerOneBoard = playerOne.gameBoard;\n  const playerTwoBoard = playerTwo.gameBoard;\n\n  function pickNextTarget() {\n    if (targetQueue.length > 0) {\n      return targetQueue.shift();\n    }\n    return {\n      row: Math.floor(Math.random() * 10),\n      col: Math.floor(Math.random() * 10),\n    };\n  }\n\n  function computerTurn() {\n    if (currentPlayer !== playerTwo) {\n      return;\n    }\n    if (playerOneBoard.areAllShipsSunk()) {\n      return;\n    }\n\n    let target = pickNextTarget();\n    let attackOnPlayer = playerOneBoard.receiveAttack(target.row, target.col);\n\n    while (attackOnPlayer === 'already attacked' || attackOnPlayer === false) {\n      target = pickNextTarget();\n      attackOnPlayer = playerOneBoard.receiveAttack(target.row, target.col);\n    }\n\n    if (attackOnPlayer === 'hit') {\n      let queueTargets = getAdjacentCoordinates(target.row, target.col);\n      targetQueue.push(...queueTargets);\n    }\n\n    updateCell(target.row, target.col, attackOnPlayer, playerOneContainer);\n    checkGameOver(playerOneBoard);\n  }\n\n  function appendPlayerBoard() {\n    const playerOneBoardContainer = document.createElement('div');\n    playerOneBoardContainer.classList.add('player-board-container');\n    playerOneContainer.classList.add('player-board');\n    const playerOneBoardText = document.createElement('h2');\n    playerOneBoardText.textContent = 'Your Board';\n    playerOneBoardContainer.append(playerOneBoardText, playerOneContainer);\n    gameBoardsContainer.appendChild(playerOneBoardContainer);\n  }\n\n  function appendComputerBoard() {\n    const playerTwoBoardContainer = document.createElement('div');\n    playerTwoBoardContainer.classList.add('computer-board-container');\n    const playerTwoBoardText = document.createElement('h2');\n    playerTwoBoardText.textContent = 'Computer Board';\n    playerTwoContainer.classList.add('computer-board');\n    playerTwoBoardContainer.append(playerTwoBoardText, playerTwoContainer);\n    gameBoardsContainer.append(playerTwoBoardContainer);\n    pageBody.appendChild(gameBoardsContainer);\n  }\n\n  function attackComputer() {\n    playerTwoContainer.addEventListener('click', (event) => {\n      if (!event.target.dataset.row || !event.target.dataset.col) {\n        return;\n      }\n      if (currentPlayer !== playerOne) {\n        return;\n      }\n      if (playerTwoBoard.areAllShipsSunk()) {\n        return;\n      }\n\n      let clickedRow = Number(event.target.dataset.row);\n      let clickedCol = Number(event.target.dataset.col);\n\n      let attackResult = playerTwoBoard.receiveAttack(clickedRow, clickedCol);\n      if (attackResult === 'already attacked') {\n        return;\n      }\n      updateCell(clickedRow, clickedCol, attackResult, playerTwoContainer);\n      checkGameOver(playerTwoBoard);\n      pageBody.appendChild(resetButtonHolder);\n      resetButtonHolder.style.display = '';\n    });\n  }\n\n  function checkGameOver(board) {\n    let boardCheck = board.areAllShipsSunk();\n    if (!boardCheck && currentPlayer === playerOne) {\n      currentPlayer = playerTwo;\n      computerTurn();\n    } else if (!boardCheck && currentPlayer === playerTwo) {\n      currentPlayer = playerOne;\n    } else if (boardCheck && currentPlayer === playerOne) {\n      alert('Game Over Player One Won The Game');\n    } else if (boardCheck && currentPlayer === playerTwo) {\n      alert('Game Over Player Two Won The Game');\n    }\n  }\n\n  function createAndPlaceComShips() {\n    const playerTwoFirstShip = new Ship(2);\n    const playerTwoSecondShip = new Ship(3);\n    const playerTwoThirdShip = new Ship(4);\n    const playerTwoFourthShip = new Ship(2);\n    const playerTwoFifthShip = new Ship(3);\n    const playerTwoSixthShip = new Ship(1);\n    const playerTwoSeventhShip = new Ship(1);\n    const playerTwoEightShip = new Ship(1);\n    const playerTwoNinthShip = new Ship(1);\n    const playerTwoTenthShip = new Ship(2);\n    placeShipRandomly(playerTwoBoard, playerTwoFirstShip);\n    placeShipRandomly(playerTwoBoard, playerTwoSecondShip);\n    placeShipRandomly(playerTwoBoard, playerTwoThirdShip);\n    placeShipRandomly(playerTwoBoard, playerTwoFourthShip);\n    placeShipRandomly(playerTwoBoard, playerTwoFifthShip);\n    placeShipRandomly(playerTwoBoard, playerTwoSixthShip);\n    placeShipRandomly(playerTwoBoard, playerTwoSeventhShip);\n    placeShipRandomly(playerTwoBoard, playerTwoEightShip);\n    placeShipRandomly(playerTwoBoard, playerTwoNinthShip);\n    placeShipRandomly(playerTwoBoard, playerTwoTenthShip);\n  }\n\n  return {\n    appendPlayerBoard,\n    appendComputerBoard,\n    createAndPlaceComShips,\n    attackComputer,\n    playerOneBoard,\n    playerTwoBoard,\n    playerOneContainer,\n    playerTwoContainer,\n  };\n}\n\nexport function clearBoards() {\n  const playerBoardContainer = document.querySelector(\n    '.player-board-container'\n  );\n  const comBoardContainer = document.querySelector('.computer-board-container');\n  if (playerBoardContainer) playerBoardContainer.remove();\n  if (comBoardContainer) comBoardContainer.remove();\n}\n","// gameplay.js\n\nimport { renderGameBoard, renderShips } from './renderGame.js';\nimport { Ship } from './ship.js';\nimport { placeShipRandomly, createGameSession } from './gameplayresources.js';\n\nexport const randomResetButton = document.createElement('button');\nrandomResetButton.textContent = 'Reset Game';\nrandomResetButton.classList.add('random-reset-button');\n\nexport const randomSwitchButton = document.createElement('button');\nrandomSwitchButton.textContent = 'Switch Mode';\nrandomSwitchButton.classList.add('random-switch-button');\n\nexport function randomBoardPlay() {\n  const gameSession = createGameSession();\n  const {\n    playerOneBoard,\n    playerOneContainer,\n    playerTwoContainer,\n    appendPlayerBoard,\n    appendComputerBoard,\n    attackComputer,\n    createAndPlaceComShips,\n  } = gameSession;\n\n  const playerOneFirstShip = new Ship(4);\n  const playerOneSecondShip = new Ship(3);\n  const playerOneThirdShip = new Ship(3);\n  const playerOneFourthShip = new Ship(2);\n  const playerOneFifthShip = new Ship(2);\n  const playerOneSixthShip = new Ship(1);\n  const playerOneSeventhShip = new Ship(1);\n  const playerOneEightShip = new Ship(1);\n  const playerOneNinthShip = new Ship(1);\n  const playerOneTenthShip = new Ship(2);\n  placeShipRandomly(playerOneBoard, playerOneFirstShip);\n  placeShipRandomly(playerOneBoard, playerOneSecondShip);\n  placeShipRandomly(playerOneBoard, playerOneThirdShip);\n  placeShipRandomly(playerOneBoard, playerOneFourthShip);\n  placeShipRandomly(playerOneBoard, playerOneFifthShip);\n  placeShipRandomly(playerOneBoard, playerOneSixthShip);\n  placeShipRandomly(playerOneBoard, playerOneSeventhShip);\n  placeShipRandomly(playerOneBoard, playerOneEightShip);\n  placeShipRandomly(playerOneBoard, playerOneNinthShip);\n  placeShipRandomly(playerOneBoard, playerOneTenthShip);\n\n  appendPlayerBoard();\n  appendComputerBoard();\n  attackComputer();\n  createAndPlaceComShips();\n  renderGameBoard(10, 10, playerOneContainer);\n  renderGameBoard(10, 10, playerTwoContainer);\n  renderShips(playerOneBoard, playerOneContainer);\n}\n","\n      import API from \"!../node_modules/style-loader/dist/runtime/injectStylesIntoStyleTag.js\";\n      import domAPI from \"!../node_modules/style-loader/dist/runtime/styleDomAPI.js\";\n      import insertFn from \"!../node_modules/style-loader/dist/runtime/insertBySelector.js\";\n      import setAttributes from \"!../node_modules/style-loader/dist/runtime/setAttributesWithoutAttributes.js\";\n      import insertStyleElement from \"!../node_modules/style-loader/dist/runtime/insertStyleElement.js\";\n      import styleTagTransformFn from \"!../node_modules/style-loader/dist/runtime/styleTagTransform.js\";\n      import content, * as namedExport from \"!!../node_modules/css-loader/dist/cjs.js!./styles.css\";\n      \n      \n\nvar options = {};\n\noptions.styleTagTransform = styleTagTransformFn;\noptions.setAttributes = setAttributes;\noptions.insert = insertFn.bind(null, \"head\");\noptions.domAPI = domAPI;\noptions.insertStyleElement = insertStyleElement;\n\nvar update = API(content, options);\n\n\n\nexport * from \"!!../node_modules/css-loader/dist/cjs.js!./styles.css\";\n       export default content && content.locals ? content.locals : undefined;\n","// selfPlacementPlay.js\n\nimport {\n  createGameSession,\n  dialog,\n  mainStagingContainer,\n  clearBoards,\n  pageBody,\n  gameBoardsContainer,\n} from './gameplayresources.js';\nimport { renderGameBoard, renderShips } from './renderGame.js';\nimport { Ship } from './ship.js';\n\nconst stagingText = document.createElement('h2');\nconst directionToggleButton = document.createElement('button');\nconst stagingContainer = document.createElement('div');\nlet currentDirection = 'vertical';\n\nexport const selfResetButton = document.createElement('button');\nselfResetButton.textContent = 'Reset Game';\nselfResetButton.classList.add('self-reset-button');\n\nexport const selfSwitchButton = document.createElement('button');\nselfSwitchButton.textContent = 'Switch Mode';\nselfSwitchButton.classList.add('random-switch-button');\n\nfunction stagingHolder() {\n  stagingText.textContent = 'Ship Staging Area';\n  directionToggleButton.classList.add('toggle-button');\n  directionToggleButton.textContent = 'Drag The Cells to Place Ship On Board';\n  stagingContainer.classList.add('ships-staging-container');\n  mainStagingContainer.append(\n    stagingText,\n    stagingContainer,\n    directionToggleButton\n  );\n  stagingContainer.style.display = '';\n  stagingText.style.display = '';\n  directionToggleButton.style.display = '';\n  gameBoardsContainer.appendChild(mainStagingContainer);\n}\n\ndirectionToggleButton.addEventListener('click', () => {\n  stagingContainer.classList.toggle('horizontal-layout');\n  currentDirection =\n    currentDirection === 'vertical' ? 'horizontal' : 'vertical';\n});\n\nexport function createPlayerGameSession() {\n  const gameSession = createGameSession();\n  const {\n    playerOneBoard,\n    playerOneContainer,\n    playerTwoContainer,\n    appendPlayerBoard,\n    appendComputerBoard,\n    attackComputer,\n    createAndPlaceComShips,\n  } = gameSession;\n\n  const playerOneShips = [\n    new Ship(4),\n    new Ship(3),\n    new Ship(3),\n    new Ship(2),\n    new Ship(2),\n    new Ship(2),\n    new Ship(1),\n    new Ship(1),\n    new Ship(1),\n    new Ship(1),\n  ];\n\n  function renderShipStaging(ships, container) {\n    const isTouchDevice =\n      'ontouchstart' in window || navigator.maxTouchPoints > 0;\n    let draggedShipIndex = null;\n    let lastHoveredCell = null;\n    let draggedShipElement = null;\n    let actualShip = null;\n\n    for (let i = 0; i < ships.length; i++) {\n      let shipContainer = document.createElement('div');\n      let shipItem = ships[i];\n\n      shipContainer.classList.add('staging-ships');\n      shipContainer.setAttribute('data-ship-index', i);\n\n      for (let j = 0; j < shipItem.length; j++) {\n        let shipCell = document.createElement('div');\n        shipCell.classList.add('staging-ship-cell');\n        shipContainer.appendChild(shipCell);\n      }\n      container.appendChild(shipContainer);\n\n      if (!isTouchDevice) {\n        shipContainer.draggable = true;\n        shipContainer.addEventListener('dragstart', (event) => {\n          event.dataTransfer.setData('shipIndex', String(i));\n        });\n      } else {\n        shipContainer.addEventListener(\n          'touchstart',\n          (event) => {\n            event.preventDefault();\n            actualShip = ships[i];\n            draggedShipElement = shipContainer;\n            draggedShipIndex = i;\n            draggedShipElement.style.position = 'fixed';\n            draggedShipElement.style.pointerEvents = 'none';\n          },\n          { passive: false }\n        );\n      }\n    }\n\n    if (!isTouchDevice) {\n      playerOneContainer.addEventListener('dragover', (event) => {\n        event.preventDefault();\n      });\n\n      playerOneContainer.addEventListener('drop', (event) => {\n        event.preventDefault();\n        if (!event.target.dataset.row || !event.target.dataset.col) {\n          return;\n        }\n        let dropRow = Number(event.target.dataset.row);\n        let dropCol = Number(event.target.dataset.col);\n        const dropData = Number(event.dataTransfer.getData('shipIndex'));\n        let dropShip = ships[dropData];\n        let shipPlacement = playerOneBoard.placeShip(\n          dropShip,\n          dropRow,\n          dropCol,\n          currentDirection\n        );\n        if (shipPlacement) {\n          renderShips(playerOneBoard, playerOneContainer);\n          let placedShip = container.querySelector(\n            `[data-ship-index=\"${dropData}\"]`\n          );\n          placedShip.remove();\n          directionToggleButton.textContent =\n            'Click Here To Change Ship Direction';\n          if (stagingContainer.childElementCount === 0) {\n            stagingContainer.style.display = 'none';\n            stagingText.style.display = 'none';\n            directionToggleButton.style.display = 'none';\n            attackComputer();\n          }\n        } else {\n          alert(\"Ship Can't be placed here\");\n        }\n      });\n    } else {\n      pageBody.addEventListener(\n        'touchmove',\n        (event) => {\n          if (draggedShipIndex === null) {\n            return;\n          }\n          event.preventDefault();\n\n          const touch = event.touches[0];\n          const xCoordinate = touch.clientX;\n          const yCoordinate = touch.clientY;\n\n          draggedShipElement.style.left = `${xCoordinate - draggedShipElement.offsetWidth / 2}px`;\n          draggedShipElement.style.top = `${yCoordinate - draggedShipElement.offsetHeight / 2}px`;\n\n          draggedShipElement.style.display = 'none';\n          const combinedCoordinates = document.elementFromPoint(\n            xCoordinate,\n            yCoordinate\n          );\n          draggedShipElement.style.display = '';\n\n          if (combinedCoordinates === null) {\n            return;\n          }\n          if (lastHoveredCell !== null) {\n            lastHoveredCell.classList.remove('hovered-cell');\n          }\n          if (\n            combinedCoordinates.dataset.row &&\n            combinedCoordinates.dataset.col\n          ) {\n            lastHoveredCell = combinedCoordinates;\n            lastHoveredCell.classList.add('hovered-cell');\n          } else {\n            lastHoveredCell = null;\n          }\n        },\n        { passive: false }\n      );\n\n      function cleanUp() {\n        if (draggedShipElement !== null) {\n          draggedShipElement.style.position = '';\n          draggedShipElement.style.pointerEvents = 'auto';\n        }\n        if (lastHoveredCell !== null) {\n          lastHoveredCell.classList.remove('hovered-cell');\n        }\n        draggedShipIndex = null;\n        draggedShipElement = null;\n      }\n\n      pageBody.addEventListener('touchend', () => {\n        if (draggedShipIndex === null || lastHoveredCell === null) {\n          cleanUp();\n          return;\n        }\n        let rowForDrop = Number(lastHoveredCell.dataset.row);\n        let colForDrop = Number(lastHoveredCell.dataset.col);\n        let droppedShip = actualShip;\n        let touchPlacement = playerOneBoard.placeShip(\n          droppedShip,\n          rowForDrop,\n          colForDrop,\n          currentDirection\n        );\n        if (touchPlacement) {\n          renderShips(playerOneBoard, playerOneContainer);\n          let placedShip = container.querySelector(\n            `[data-ship-index=\"${draggedShipIndex}\"]`\n          );\n          placedShip.remove();\n          directionToggleButton.textContent =\n            'Click Here To Change Ship Direction';\n          if (stagingContainer.childElementCount === 0) {\n            stagingContainer.style.display = 'none';\n            stagingText.style.display = 'none';\n            directionToggleButton.style.display = 'none';\n            attackComputer();\n          }\n          cleanUp();\n        } else {\n          alert(\"Ship Can't be placed here\");\n          cleanUp();\n        }\n      });\n    }\n  }\n\n  stagingHolder();\n  appendPlayerBoard();\n  appendComputerBoard();\n  renderGameBoard(10, 10, playerOneContainer);\n  renderGameBoard(10, 10, playerTwoContainer);\n  renderShipStaging(playerOneShips, stagingContainer);\n  renderShips(playerOneBoard, playerOneContainer);\n  createAndPlaceComShips();\n}\n\nexport function selfPlacementGame() {\n  clearBoards();\n  createPlayerGameSession();\n  dialog.close();\n}\n","// appController.js\n\nimport {\n  selfPlacementGame,\n  selfResetButton,\n  selfSwitchButton,\n} from './selfplacementplay.js';\nimport {\n  randomBoardPlay,\n  randomResetButton,\n  randomSwitchButton,\n} from './gameplay.js';\nimport {\n  pageBody,\n  clearBoards,\n  resetButtonHolder,\n  dialog,\n} from './gameplayresources.js';\n\nconst randomPlacementButton = document.querySelector(\n  '.random-placement-button'\n);\nrandomPlacementButton.addEventListener('click', () => {\n  resetButtonHolder.append(randomResetButton, randomSwitchButton);\n  pageBody.appendChild(resetButtonHolder);\n  dialog.close();\n});\n\nexport const selfPlacementButton = document.querySelector(\n  '.self-placement-button'\n);\n\nselfPlacementButton.addEventListener('click', () => {\n  resetButtonHolder.append(selfResetButton, selfSwitchButton);\n  pageBody.appendChild(resetButtonHolder);\n  selfPlacementGame();\n});\n\nrandomResetButton.addEventListener('click', () => {\n  resetButtonHolder.style.display = 'none';\n  clearBoards();\n  randomBoardPlay();\n});\n\nrandomSwitchButton.addEventListener('click', () => {\n  resetButtonHolder.style.display = 'none';\n  clearBoards();\n  resetButtonHolder.replaceChildren();\n  resetButtonHolder.append(selfResetButton, selfSwitchButton);\n  pageBody.append(resetButtonHolder);\n  selfPlacementGame();\n});\n\nselfResetB